-- ═══════════════════════════════════════════════════════════════
-- CheckOn 위험신호 검증 시드 — 학생 17명 × 12주
-- 작성 2026-08-13 · AI 파트 → 백엔드
--
-- 🔴 실행 전에 §1 두 곳(:teacher_id · :monday)과 §2 매핑 2개를 채우세요.
-- 🔴 전체가 한 트랜잭션입니다. 검증(§6)까지 보고 COMMIT 하세요.
-- ═══════════════════════════════════════════════════════════════

\set ON_ERROR_STOP on
BEGIN;

-- ───────────────────────────────────────────────────────────────
-- §1. 🔴 채울 것 ①  — 강사와 기준 주
-- ───────────────────────────────────────────────────────────────
--   teacher_id : account_id 가 아니라 🔴 teacher_profile_id
--   monday     : 기준이 될 "이번 주 월요일" (KST). week_offset=0 이 이 주다.

\set teacher_id '0198f000-0000-7000-8000-000000000001'
\set monday     '2026-08-10'

-- ───────────────────────────────────────────────────────────────
-- §2. 🔴 채울 것 ② — 문서 별칭 ↔ 실제 alias 매핑
-- ───────────────────────────────────────────────────────────────
--   CSV 의 st_01 ~ st_17 은 사람이 읽는 이름입니다.
--   실제 ai_student_aliases.alias 는 st_ + 32자리 hex 라 그대로 못 씁니다.
--   Roster 를 만드신 뒤, 어느 학생이 어느 시나리오인지 여기에 이어 주세요.
--   (각 학생이 무엇을 겨냥하는지는 §3 주석 참고)

CREATE TEMP TABLE seed_student_map (doc_alias text PRIMARY KEY, real_alias text NOT NULL);

CREATE TEMP TABLE seed_class_map (doc_alias text PRIMARY KEY, class_group_id uuid);
--   반 미배정 학생(st_16)은 class_alias 가 비어 있어 class_group_id 가 NULL 로 들어갑니다.

-- ───────────────────────────────────────────────────────────────
-- §3. 스테이징 — CSV 원본 그대로
-- ───────────────────────────────────────────────────────────────
--   week_offset 0 = 이번 주 · 11 = 11주 전 · dow 0=월 … 6=일
--   🔴 occurred_at 은 KST 로 조립한 뒤 UTC 로 저장합니다.
--      (KST 월 00:00 = UTC 일 15:00 — 이 순서를 지켜야 주 버킷이 안 밀립니다)

CREATE TEMP TABLE seed_lr (
  student_alias text, class_alias text, week_offset int, dow int, time_kst text,
  record_type text, source_type text, correct text, duration_sec text,
  passage_word_count text, area_tag text, subject_track text, type_tag text,
  item_format text, assignment_title_text text
);

CREATE TEMP TABLE seed_asg (student_alias text, week_offset int, expected_count int, submitted_count int);

-- ───────────────────────────────────────────────────────────────
-- §4. 🔴 매핑이 다 채워졌는지 먼저 막는다
-- ───────────────────────────────────────────────────────────────
DO $$
DECLARE missing int;
BEGIN
  -- 실제 alias 는 st_ + 32자리 hex = 35자다. 자리표시자는 길이가 다르다.
  SELECT count(*) INTO missing FROM seed_student_map m
   WHERE m.real_alias !~ '^st_[0-9a-f]{32}$';
  IF missing > 0 THEN
    RAISE EXCEPTION '🔴 seed_student_map 에 안 채운 행이 % 개 있습니다 (§2)', missing;
  END IF;
  IF EXISTS (SELECT 1 FROM seed_class_map WHERE class_group_id IS NULL) THEN
    RAISE EXCEPTION '🔴 seed_class_map 의 반 UUID 를 채우세요 (§2)';
  END IF;
  IF EXISTS (
    SELECT 1 FROM seed_student_map m
     LEFT JOIN ai_student_aliases sa ON sa.alias = m.real_alias
    WHERE sa.student_id IS NULL) THEN
    RAISE EXCEPTION '🔴 ai_student_aliases 에 없는 alias 가 있습니다 — Roster 를 먼저 만드세요';
  END IF;
END $$;

-- ───────────────────────────────────────────────────────────────
-- §5. 적재
-- ───────────────────────────────────────────────────────────────

  id, teacher_id, student_id, class_group_id, record_type, occurred_at, source_type,
  correct, duration_sec, passage_word_count, area_tag, subject_track, type_tag,
  item_format, assignment_title_text, created_at, updated_at)
SELECT
  gen_random_uuid(),                      -- 🔴 v7 을 쓰신다면 이 함수만 바꾸세요
  :'teacher_id'::uuid,
  sa.student_id,
  cm.class_group_id,
  s.record_type,
  ((:'monday'::date - (s.week_offset * 7) + s.dow)::timestamp + s.time_kst::time)
      AT TIME ZONE 'Asia/Seoul',          -- 🔴 KST 로 조립 → UTC 저장
  s.source_type,
  s.correct::boolean,
  s.duration_sec::int,
  s.passage_word_count::int,
  s.area_tag, s.subject_track, s.type_tag, s.item_format, s.assignment_title_text,
  now(), now()
FROM seed_lr s
JOIN seed_student_map m  ON m.doc_alias = s.student_alias
JOIN ai_student_aliases sa ON sa.alias = m.real_alias AND sa.teacher_id = :'teacher_id'::uuid
LEFT JOIN seed_class_map cm ON cm.doc_alias = NULLIF(s.class_alias, '');

-- 과제 주간 집계 — ⚠ 이번 라운드에서는 요청 생성 로직이 이 테이블을 안 읽습니다.
--   R2 를 요청에 싣는 작업이 끝난 뒤에 의미가 생깁니다. 미리 넣어 둡니다.
  teacher_id, student_id, week_start, expected_count, submitted_count, calculated_at)
SELECT
  :'teacher_id'::uuid, sa.student_id,
  (:'monday'::date - (a.week_offset * 7)),
  a.expected_count, a.submitted_count, now()
FROM seed_asg a
JOIN seed_student_map m  ON m.doc_alias = a.student_alias
JOIN ai_student_aliases sa ON sa.alias = m.real_alias AND sa.teacher_id = :'teacher_id'::uuid
ON CONFLICT (teacher_id, student_id, week_start) DO UPDATE
  SET expected_count = EXCLUDED.expected_count,
      submitted_count = EXCLUDED.submitted_count,
      calculated_at   = EXCLUDED.calculated_at;

-- ───────────────────────────────────────────────────────────────
-- §6. 🔴 검증 — COMMIT 하기 전에 보세요
-- ───────────────────────────────────────────────────────────────

\echo '── ① 반별 학생 수 (기대: cl_a1=9 · cl_b2=7 · 미배정=1)'
SELECT COALESCE(cg.name,'(미배정)') AS class, count(DISTINCT lr.student_id) AS students
FROM learning_records lr LEFT JOIN class_groups cg ON cg.id = lr.class_group_id
WHERE lr.teacher_id = :'teacher_id'::uuid GROUP BY 1 ORDER BY 1;

\echo '── ② 주간 활동량 (기대: R3=2 · 복합=4 · 복귀학생 3주 공백 · 나머지 9 이상)'
SELECT m.doc_alias,
       array_agg(cnt ORDER BY wk DESC) AS weekly_activity_w0_to_w11
FROM (
  SELECT lr.student_id,
         date_trunc('week', (lr.occurred_at AT TIME ZONE 'Asia/Seoul'))::date AS wk,
         count(*) AS cnt
  FROM learning_records lr WHERE lr.teacher_id = :'teacher_id'::uuid
  GROUP BY 1,2) t
JOIN ai_student_aliases sa ON sa.student_id = t.student_id AND sa.teacher_id = :'teacher_id'::uuid
JOIN seed_student_map m ON m.real_alias = sa.alias
GROUP BY 1 ORDER BY 1;

\echo '── ③ 주간 정답률 (기대: R1 학생만 최근 2주가 낮다)'
SELECT m.doc_alias,
       array_agg(acc ORDER BY wk DESC) AS accuracy_w0_to_w11
FROM (
  SELECT lr.student_id,
         date_trunc('week', (lr.occurred_at AT TIME ZONE 'Asia/Seoul'))::date AS wk,
         round(avg(CASE WHEN lr.correct THEN 1 ELSE 0 END)::numeric, 2) AS acc
  FROM learning_records lr
  WHERE lr.teacher_id = :'teacher_id'::uuid AND lr.record_type='SOLVE' AND lr.correct IS NOT NULL
  GROUP BY 1,2) t
JOIN ai_student_aliases sa ON sa.student_id = t.student_id AND sa.teacher_id = :'teacher_id'::uuid
JOIN seed_student_map m ON m.real_alias = sa.alias
GROUP BY 1 ORDER BY 1;

\echo '── ④ 값 집합 (기대: SOLVE/SUBMIT · MANUAL · mcq · 조합제약 준수)'
SELECT DISTINCT record_type FROM learning_records WHERE teacher_id = :'teacher_id'::uuid;
SELECT DISTINCT source_type FROM learning_records WHERE teacher_id = :'teacher_id'::uuid;
SELECT DISTINCT area_tag, subject_track FROM learning_records
WHERE teacher_id = :'teacher_id'::uuid ORDER BY 1,2;

\echo '── ⑤ R4 skip 학생만 duration 이 전부 NULL 인가'
SELECT m.doc_alias,
       count(*) FILTER (WHERE lr.duration_sec IS NULL) AS null_dur, count(*) AS total
FROM learning_records lr
JOIN ai_student_aliases sa ON sa.student_id = lr.student_id AND sa.teacher_id = lr.teacher_id
JOIN seed_student_map m ON m.real_alias = sa.alias
WHERE lr.teacher_id = :'teacher_id'::uuid AND lr.record_type='SOLVE'
GROUP BY 1 ORDER BY 2 DESC;

\echo '── ⑥ 재원 주수 (기대: 신규생 1명만 2 미만)'
SELECT m.doc_alias, r.started_at,
       floor(EXTRACT(EPOCH FROM ((:'monday'::date + 7) - r.started_at))/604800) AS enrolled_weeks
FROM teacher_student_relationships r
JOIN ai_student_aliases sa ON sa.student_id = r.student_id AND sa.teacher_id = r.teacher_id
JOIN seed_student_map m ON m.real_alias = sa.alias
WHERE r.teacher_id = :'teacher_id'::uuid ORDER BY 3;

-- ───────────────────────────────────────────────────────────────
-- §7. 🔴 여기서 판단
-- ───────────────────────────────────────────────────────────────
--   위 ①~⑥ 이 기대와 맞으면      →  COMMIT;
--   하나라도 어긋나면              →  ROLLBACK;  (아무것도 안 남습니다)
--
--   COMMIT 후 배치:
--     POST /api/v1/detection-runs  {"analysisDate": "<기준 주 안의 날짜>"}
--     GET  /api/v1/detection-runs/{runId}   → SUCCEEDED 대기
--
--   ⚠ 반복 검증 시 analysisDate 를 하루씩 밀어서 돌리세요 —
--     동일 강사·동일 analysisDate 는 같은 실행을 재사용합니다.

\echo ''
\echo '🔴 위 검증 결과를 확인하고 COMMIT; 또는 ROLLBACK; 을 입력하세요.'
